use vstd::prelude::*;

verus! {

// Specification function: all elements in a sequence are equal
spec fn all_equal(v: Seq<i32>) -> bool {
    forall|i: int, j: int| 0 <= i < v.len() && 0 <= j < v.len() ==> v[i] == v[j]
}

fn mall_equal1(v: &[i32]) -> (result: bool)
    ensures
        result == all_equal(v@),
{
    if v.len() == 0 {
        return true;
    }
    
    let first = v[0];
    let mut i: usize = 1;
    
    while i < v.len()
        invariant
            0 < i <= v.len(),
            v.len() > 0,
            first == v@[0],
            forall|k: int| 0 <= k < i ==> v@[k] == first,
    {
        if v[i] != first {
            assert(v@[i] != v@[0]);
            assert(!all_equal(v@));
            return false;
        }
        i = i + 1;
    }
    
    assert(forall|k: int| 0 <= k < v@.len() ==> v@[k] == first);
    assert(forall|i: int, j: int| 0 <= i < v@.len() && 0 <= j < v@.len() ==> v@[i] == first && v@[j] == first);
    
    true
}

}

